fn check_favorable_engage_formation(version, player, data, target_enemy, engage_range) -> bool

// --- 준비 (1203~1204)
team = player.info.team            // >=2 이면 panic_bounds_check(len=2)
pos  = player.info.position.as_index()
champ = data.cache.player_champion[team][pos].unwrap()   // None 이면 panic
enemy_team = 1 - team

// --- 게이트 1: 적 위치로 붙으면 미니언에게 맞는가 (1208~1209)
d = minion_wave_risk::enemy_minion_line_action_danger_damage_at(
        version, data, champ,
        target_enemy.x, target_enemy.y,
        data.context.setting.tick_per_second * 2,
        true, false)
if d != 0 { return false }          // 미니언 피해가 예상되면 대형 볼 것 없이 불리

// --- 적의 퇴로 벡터 (1214~1223)
(elx, ely, erx, ery) = data.context.map.fountain(enemy_team)
enemy_base_x = (elx + erx) / 2      // (add 후 lshr 1)
enemy_base_y = (ely + ery) / 2
retreat_dx = (enemy_base_x as i128) - (target_enemy.x as i128)
retreat_dy = (enemy_base_y as i128) - (target_enemy.y as i128)
retreat_len_sq = retreat_dx^2 + retreat_dy^2
if retreat_len_sq < 1 { return true }   // 적이 이미 자기 분수 중심 = 퇴로 정의 불가 → 유리로 간주

// --- 미리 계산되는 값 (LLVM 이 루프 밖으로 호이스팅)
max_engage_dist   = engage_range + 100000
enemy_to_base_sq  = distance_sq(target_enemy.x, target_enemy.y, enemy_base_x, enemy_base_y)

// --- 아군 대형 집계 (1229~1313)
front_allies = 0; flank_allies = 0; rear_allies = 0
for ap in 0..5 {
    ally = data.cache.player_champion[team][ap]
    if ally.is_none() { continue }                       // 1234
    if ally.id == champ.id { continue }                  // 1235 (자기 자신 제외)
    if ally.hp * 100 / ally.stat_cached.hp < 40 { continue }   // 1240 (체력 40% 미만 제외)

    ally_to_enemy_dist_sq = distance_sq(ally.x, ally.y, target_enemy.x, target_enemy.y)  // 1245
    if ally_to_enemy_dist_sq > max_engage_dist * max_engage_dist { continue }            // 1247

    ally_dx = (target_enemy.x as i128) - (ally.x as i128)    // 1252  (아군 -> 적 벡터)
    ally_dy = (target_enemy.y as i128) - (ally.y as i128)    // 1253
    ally_len_sq = ally_dx^2 + ally_dy^2                       // 1254
    if ally_len_sq < 1 { front_allies += 1; continue }        // 1256~1258 (겹쳐 있음)

    dot            = ally_dx*retreat_dx + ally_dy*retreat_dy  // 1264
    cross          = ally_dx*retreat_dy - ally_dy*retreat_dx  // 1267
    len_product_sq = ally_len_sq * retreat_len_sq             // 1270
    dot_sq         = dot*dot                                  // 1278
    cross_sq       = cross*cross                              // 1279

    is_front             = dot > 0 && dot_sq * 4   > len_product_sq        // 1280
    is_rear_direction    = dot < 0 && dot_sq * 100 > len_product_sq * 9    // 1283
    is_significant_flank =            cross_sq * 100 > len_product_sq * 9  // 1286

    if is_front {                     // 1288
        front_allies += 1             // 1289
    } else if is_rear_direction {     // 1290
        to_base_dist_sq       = distance_sq(ally.x, ally.y, enemy_base_x, enemy_base_y)  // 1293
        enemy_to_base_dist_sq = enemy_to_base_sq                                         // 1294
        if to_base_dist_sq < enemy_to_base_dist_sq {  // 1296  아군이 적보다 적 본진에 더 가깝다
            rear_allies += 1                          // 1298  (퇴로 차단 성공)
        } else {
            flank_allies += 1                         // 1300
        }
    } else if is_significant_flank {  // 1302
        flank_allies += 1             // 1304
    } else {
        front_allies += 1             // 1307
    }
}

// --- 최종 판정 (1316~1340)
if rear_allies > 0 { return true }                                        // 1316
if flank_allies > 1 || (flank_allies > 0 && front_allies > 0) { return true }  // 1321
if front_allies > 1 {                                                     // 1331
    // enemy_to_base_sq 는 위에서 계산한 값 재사용 (LLVM CSE)              // 1334
    champ_to_base_sq = distance_sq(champ.x, champ.y, enemy_base_x, enemy_base_y)  // 1335
    return champ_to_base_sq * 5 <= enemy_to_base_sq * 6                   // 1340
}
return false

// 기하 해석: retreat 벡터는 '적 -> 적 본진'. ally 벡터는 '아군 -> 적'.
//  dot>0 = 아군이 적 본진 반대편(적을 본진 쪽으로 밀어내는 위치) -> front
//  dot<0 = 아군이 적과 적 본진 사이(퇴로 위) -> 추가로 적보다 본진에 더 가까우면 rear, 아니면 flank
//  퇴로축에서 크게 벗어난 각도 -> flank
